/* Installation/offline state only. Does not move or clear project data. */
(()=>{
 const status=document.getElementById('offlineStatus'),detail=document.getElementById('offlineDetail'),install=document.getElementById('installApp'),check=document.getElementById('checkOfflineUpdate'),update=document.getElementById('applyOfflineUpdate'),help=document.getElementById('offlineHelp');
 let registration,installPrompt,ready=false,applying=false,checking=false;
 const installed=()=>window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
 function paint(){status.textContent=ready?(navigator.onLine?'Offline ready':'Offline · ready'):(navigator.onLine?'Preparing offline use…':'Offline setup incomplete');status.dataset.ready=String(ready);install.textContent=installed()?'App installed':'Install app';install.disabled=installed();if(ready)detail.textContent='App files are saved on this device. Projects and uploads stay in this browser; no connection is needed for analysis.';else if(!navigator.onLine)detail.textContent='Open this app online once and wait for Offline ready before taking it into the field.';}
 async function inspect(){if(!registration?.active)return;try{const result=await new Promise((resolve,reject)=>{const channel=new MessageChannel(),timeout=setTimeout(()=>reject(Error('Offline readiness check timed out.')),8000);channel.port1.onmessage=event=>{clearTimeout(timeout);channel.port1.close();resolve(event.data)};registration.active.postMessage({type:'OFFLINE_STATUS'},[channel.port2])});ready=!!result.ready;paint();if(!ready&&navigator.onLine)detail.textContent='Some app files have not been saved. Stay online and reload, then check again.';}catch(error){ready=false;paint();detail.textContent='Offline readiness could not be verified. Stay online, reload and check again.'}}
 function offerUpdate(){if(registration?.waiting){update.hidden=false;detail.textContent='An app update is downloaded. Save any reading edits, then choose Apply update. Saved projects will be kept.'}}
 function watch(){offerUpdate();registration.addEventListener('updatefound',()=>{const worker=registration.installing;if(!worker)return;worker.addEventListener('statechange',()=>{if(worker.state==='installed'){if(navigator.serviceWorker.controller)setTimeout(offerUpdate,0);else navigator.serviceWorker.ready.then(inspect)}if(worker.state==='redundant'&&!ready){status.textContent='Offline setup failed';detail.textContent='The required app files could not be saved. Reconnect and reload before using the app offline.'}})})}
 window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;paint()});window.addEventListener('appinstalled',()=>{installPrompt=null;paint()});window.addEventListener('online',()=>{paint();inspect();registration?.update().catch(()=>{})});window.addEventListener('offline',()=>{paint();inspect()});
 install.onclick=async()=>{if(installPrompt){const prompt=installPrompt;installPrompt=null;await prompt.prompt();await prompt.userChoice;paint()}else{help.open=true;detail.textContent='Use your browser’s Install app option. On iPhone/iPad, open in Safari and choose Share → Add to Home Screen. Wait for Offline ready before disconnecting.'}};
 check.onclick=async()=>{if(checking)return;checking=true;check.disabled=true;try{if(registration&&navigator.onLine)await registration.update();await inspect();offerUpdate()}catch(error){detail.textContent=ready?'Saved app files are available offline; an online update check could not complete.':'Could not prepare offline use. Check your connection and reload.'}finally{checking=false;check.disabled=false}};
 update.onclick=async()=>{if(!registration?.waiting)return;if(typeof save==='function'){const saved=await save();if(saved===false){detail.textContent='Your current workspace could not be saved. Export a backup before applying this update.';return}}applying=true;update.disabled=true;registration.waiting.postMessage({type:'APPLY_UPDATE'})};
 if(!('serviceWorker'in navigator)||!window.isSecureContext){status.textContent='Offline installation unavailable';detail.textContent='Open the HTTPS site directly in a supported browser. Analysis still works while this page is open.';check.disabled=true;install.disabled=true;return}
 navigator.serviceWorker.addEventListener('controllerchange',()=>{if(applying){location.reload();return}inspect()});
 paint();(async()=>{const existing=await navigator.serviceWorker.getRegistration('./'),expected=new URL('./sw.js',location.href).href,ours=existing&&[existing.active,existing.waiting,existing.installing].some(worker=>worker?.scriptURL===expected);return ours?existing:navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'})})().then(async reg=>{registration=reg;watch();await navigator.serviceWorker.ready;await inspect();offerUpdate();if(navigator.onLine)reg.update().catch(()=>{})}).catch(error=>{status.textContent='Offline installation unavailable';detail.textContent='This browser or hosting environment could not register offline support. Try opening the site directly in Chrome, Edge or Safari.';ready=false});
})();
